func (r *owaMailboxPolicyResource) Configure(_ context.Context, req resource.ConfigureRequest, _ *resource.ConfigureResponse) {
	if req.ProviderData == nil {
		return
	}
	r.client = req.ProviderData.(*clients.Client)
}

func (r *owaMailboxPolicyResource) Create(ctx context.Context, req resource.CreateRequest, resp *resource.CreateResponse) {
	var plan owaMailboxPolicyModel
	resp.Diagnostics.Append(req.Plan.Get(ctx, &plan)...)
	if resp.Diagnostics.HasError() {
		return
	}

	p := exo.NewOwaMailboxPolicyParams{
		IsDefault: plan.IsDefault.ValueBool(),
		Name:      plan.Name.ValueString(),
	}
	if resp.Diagnostics.HasError() {
		return
	}
	res, err := r.client.EXO.NewOwaMailboxPolicy(ctx, p)
	if err != nil {
		resp.Diagnostics.AddError("New-OwaMailboxPolicy failed", err.Error())
		return
	}
	obj := firstObject(res.Value)
	if obj == nil {
		resp.Diagnostics.AddError("New-OwaMailboxPolicy returned no object", "the cmdlet did not return the created object")
		return
	}
	cfg := plan
	ident := firstNonEmptyStr(getString(obj, "Identity"), getString(obj, "Guid"), getString(obj, "Name"))
	if !r.refresh(ctx, ident, &plan, &resp.Diagnostics, nil) {
		if resp.Diagnostics.HasError() {
			return
		}
		readOwaMailboxPolicy(ctx, obj, &plan)
	}
	r.reconcileState(&cfg, &plan)
	resp.Diagnostics.Append(resp.State.Set(ctx, &plan)...)
}

func (r *owaMailboxPolicyResource) Read(ctx context.Context, req resource.ReadRequest, resp *resource.ReadResponse) {
	var state owaMailboxPolicyModel
	resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
	if resp.Diagnostics.HasError() {
		return
	}
	if !r.refresh(ctx, r.identityOf(state), &state, &resp.Diagnostics, nil) {
		if !resp.Diagnostics.HasError() {
			resp.State.RemoveResource(ctx)
		}
		return
	}
	resp.Diagnostics.Append(resp.State.Set(ctx, &state)...)
}

